import socket, time
for host in ['1.1.1.1', 'google.com', 'microsoft.com']:
    try:
        ip = socket.gethostbyname(host)
        t = time.time()
        s = socket.create_connection((ip, 443), timeout=5)
        print('%-14s -> %-15s TCP 443 connected in %.1f ms' % (host, ip, (time.time() - t) * 1000))
        s.close()
    except OSError as e:
        print('%-14s -> failed: %s' % (host, e))
